class HallucinationDetector(BaseEstimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        """
        Detects hallucinations by measuring the variance of log-probabilities across the sequence.

        Approach: Calculates the variance of the log-probability sequence for each sample.
        Hypothesis: Hallucinated sequences exhibit higher variance in model confidence (log-probs) 
        compared to truthful sequences, as the model struggles to maintain consistent confidence 
        when generating non-existent facts.

        Note: This explores the 'positional change in confidence' signal family, differing from 
        the previous 'total confidence' (sum) approach.
        """
        scores = []
        for seq_logprobs in stats["sequence_logprobs"]:
            # Ensure we have enough tokens to calculate variance
            if len(seq_logprobs) > 1:
                # Calculate variance of the log-probability sequence
                var_score = np.var(seq_logprobs, dtype=np.float32)
            else:
                # Fallback for very short sequences (treat as low hallucination risk)
                var_score = 0.0
            scores.append(var_score)

        return np.array(scores, dtype=np.float32)

class HallucinationDetector(Estimator):
    def __init__(self, context: Dict[str, Any]) -> None:
        super().__init__(
            context,
            stats_dependencies=[
                "sequence_logprobs",
            ],
            level="sequence",
        )

    def __call__(self, stats: Dict[str, np.ndarray]) -> np.ndarray:
        # Calculate variance of log-probs for each sequence
        # Hallucinations often exhibit higher variance in token confidence
        variances = np.array([
            np.var(seq_logprobs, ddof=0) 
            for seq_logprobs in stats["sequence_logprobs"]
        ], dtype=np.float32)
        return variances
